//! Waypoint flight paths, their validation and predefined templates.
//!
//! The flight path describes the **en-route** part of the mission between the
//! initial climb and the approach. Take-off, approach and landing are generated by
//! the state machine and are not part of the waypoint list.
//!
//! A waypoint with `speed_m_s == 0` is a *hover waypoint*: the vehicle decelerates,
//! holds position until the altitude (and heading, if given) is captured, then
//! continues. Other waypoints are flown through.

use airship_model::math::wrap_pi;
use airship_model::{AirshipParams, ValidationReport, Vec2};
use serde::{Deserialize, Serialize};

use crate::config::AutopilotConfig;
use crate::guidance::ApproachGeometry;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Waypoint {
    pub x_m: f64,
    pub y_m: f64,
    /// Target gear height above ground (m).
    pub altitude_m: f64,
    /// Target heading at the waypoint (compass deg), only used by hover waypoints.
    pub heading_deg: Option<f64>,
    /// Desired ground speed on the leg toward this waypoint (m/s); 0 = hover waypoint.
    pub speed_m_s: f64,
    /// Acceptance radius (m).
    pub tolerance_m: f64,
}

impl Waypoint {
    pub fn position(&self) -> Vec2 {
        Vec2::new(self.x_m, self.y_m)
    }

    pub fn is_hover(&self) -> bool {
        self.speed_m_s < 0.3
    }
}

#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct FlightPath {
    pub name: String,
    pub waypoints: Vec<Waypoint>,
}

/// Validate a path for the given vehicle and autopilot configuration.
/// `start` is the take-off site (the first leg starts there).
pub fn validate_flight_path(
    path: &FlightPath,
    start: Vec2,
    vehicle: &AirshipParams,
    ap: &AutopilotConfig,
) -> ValidationReport {
    let mut r = ValidationReport::new();
    if path.waypoints.len() > 100 {
        r.error("waypoints", "at most 100 waypoints are supported");
    }
    let lim = &vehicle.limits;
    let mut prev_pos = start;
    let mut prev_alt = ap.target_altitude_m;
    let mut prev_tol: f64 = 0.0;
    for (i, w) in path.waypoints.iter().enumerate() {
        let f = format!("waypoints[{i}]");
        if !(w.x_m.is_finite() && w.y_m.is_finite()) || w.x_m.abs() > 1e5 || w.y_m.abs() > 1e5 {
            r.error(
                format!("{f}.x_m"),
                "coordinates must be finite and within +/-100 km",
            );
            continue;
        }
        if r.range(&format!("{f}.altitude_m"), w.altitude_m, 0.0, 2000.0, "m")
            && w.altitude_m < ap.safety.min_enroute_altitude_m
        {
            r.error(
                format!("{f}.altitude_m"),
                format!(
                    "below the minimum en-route altitude of {} m",
                    ap.safety.min_enroute_altitude_m
                ),
            );
        }
        r.range(
            &format!("{f}.speed_m_s"),
            w.speed_m_s,
            0.0,
            lim.max_airspeed_m_s,
            "m/s",
        );
        r.range(&format!("{f}.tolerance_m"), w.tolerance_m, 1.0, 500.0, "m");
        if let Some(h) = w.heading_deg {
            r.range(&format!("{f}.heading_deg"), h, 0.0, 360.0, "deg");
            if !w.is_hover() {
                r.warning(
                    format!("{f}.heading_deg"),
                    "target heading is only enforced at hover waypoints (speed 0)",
                );
            }
        }
        let leg = (w.position() - prev_pos).norm();
        if i > 0 && leg < prev_tol.max(w.tolerance_m) {
            r.error(
                f.clone(),
                "waypoint lies inside the acceptance radius of the previous waypoint",
            );
        }
        // Climb-gradient feasibility of the leg at its speed.
        let speed = if w.is_hover() {
            ap.guidance.hold_max_speed_m_s
        } else {
            w.speed_m_s
        };
        if leg > 1.0 && speed > 0.0 {
            let dh = w.altitude_m - prev_alt;
            let required = dh * speed / leg;
            let (limit, what) = if dh > 0.0 {
                (lim.max_climb_rate_m_s, "climb")
            } else {
                (lim.max_descent_rate_m_s, "descent")
            };
            if required.abs() > limit {
                r.warning(
                    format!("{f}.altitude_m"),
                    format!(
                        "leg requires a {what} rate of {:.2} m/s at {:.1} m/s, above the {limit} m/s limit: the altitude will lag the path",
                        required.abs(),
                        speed
                    ),
                );
            }
        }
        // Turn feasibility: minimum turn radius at the leg speed.
        if let Some(next) = path.waypoints.get(i + 1) {
            let a = (w.position() - prev_pos).angle();
            let b = (next.position() - w.position()).angle();
            let turn = wrap_pi(b - a).abs();
            let radius = speed / lim.max_turn_rate_deg_s.to_radians();
            let needed = radius * (turn / 2.0).tan().abs();
            if turn > 0.1 && needed > w.tolerance_m.max(ap.guidance.lookahead_m) * 2.0 {
                r.warning(
                    f.clone(),
                    format!(
                        "{:.0} deg turn at {:.1} m/s needs about {:.0} m to complete (turn radius {:.0} m); expect overshoot",
                        turn.to_degrees(),
                        speed,
                        needed,
                        radius
                    ),
                );
            }
        }
        prev_pos = w.position();
        prev_alt = w.altitude_m;
        prev_tol = w.tolerance_m;
    }
    r
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PathTemplate {
    VerticalClimb,
    ClimbAndLevel,
    StraightApproach,
    CurvedApproach,
    DescentToLanding,
    GoAroundClimbOut,
}

impl PathTemplate {
    pub const ALL: [PathTemplate; 6] = [
        PathTemplate::VerticalClimb,
        PathTemplate::ClimbAndLevel,
        PathTemplate::StraightApproach,
        PathTemplate::CurvedApproach,
        PathTemplate::DescentToLanding,
        PathTemplate::GoAroundClimbOut,
    ];

    pub fn description(self) -> &'static str {
        match self {
            PathTemplate::VerticalClimb => {
                "Steep powered climb over the take-off site to a hover waypoint, then direct to the approach"
            }
            PathTemplate::ClimbAndLevel => {
                "Climb-out along the take-off heading followed by a level leg"
            }
            PathTemplate::StraightApproach => {
                "Direct leg to a point on the extended final-approach course"
            }
            PathTemplate::CurvedApproach => {
                "Arc of waypoints that turns onto the final-approach course"
            }
            PathTemplate::DescentToLanding => {
                "Legs of decreasing altitude toward the approach gate"
            }
            PathTemplate::GoAroundClimbOut => {
                "Low pass over the landing point, climb-out and circuit back to the approach"
            }
        }
    }
}

fn wp(p: Vec2, alt: f64, speed: f64, tol: f64) -> Waypoint {
    Waypoint {
        x_m: round1(p.x),
        y_m: round1(p.y),
        altitude_m: round1(alt),
        heading_deg: None,
        speed_m_s: speed,
        tolerance_m: tol,
    }
}

fn round1(v: f64) -> f64 {
    (v * 10.0).round() / 10.0
}

/// Generate a template path between `takeoff` and the approach defined by `geometry`.
pub fn path_template(
    t: PathTemplate,
    takeoff: Vec2,
    geometry: &ApproachGeometry,
    ap: &AutopilotConfig,
) -> FlightPath {
    let cruise_alt = ap.target_altitude_m;
    let v = ap.cruise_speed_m_s;
    let app_alt = ap.approach.altitude_m;
    let u = geometry.course_dir;
    // Point on the extended final course beyond the pre-gate, and its lateral neighbour.
    let pregate = geometry.pregate();
    let left = Vec2::new(-u.y, u.x);
    let waypoints = match t {
        PathTemplate::VerticalClimb => vec![Waypoint {
            heading_deg: Some(airship_model::math::yaw_to_heading_deg(geometry.course_yaw)),
            ..wp(takeoff, cruise_alt.max(app_alt + 10.0), 0.0, 5.0)
        }],
        PathTemplate::ClimbAndLevel => {
            let dir = (pregate - takeoff).normalized();
            let dir = if dir.norm() < 0.5 {
                Vec2::new(1.0, 0.0)
            } else {
                dir
            };
            vec![
                wp(takeoff + dir * 150.0, cruise_alt, v, 15.0),
                wp(takeoff + dir * 350.0, cruise_alt, v, 15.0),
            ]
        }
        PathTemplate::StraightApproach => vec![wp(
            pregate - u * 60.0,
            app_alt.max(cruise_alt.min(app_alt + 10.0)),
            v,
            15.0,
        )],
        PathTemplate::CurvedApproach => {
            // Counter-clockwise quarter arc of radius r whose end point lies on the
            // extended final course 20 m before the pre-gate with tangent `u`.
            let r = 90.0;
            let end = pregate - u * 20.0;
            let center = end + left * r;
            let end_angle = (end - center).angle();
            (0..5)
                .map(|k| {
                    let a = end_angle - std::f64::consts::FRAC_PI_2 * (1.0 - k as f64 / 4.0);
                    let p = center + Vec2::new(a.cos(), a.sin()) * r;
                    wp(
                        p,
                        cruise_alt + (app_alt - cruise_alt) * k as f64 / 4.0,
                        v.min(4.5),
                        12.0,
                    )
                })
                .collect()
        }
        PathTemplate::DescentToLanding => {
            let start = takeoff + (pregate - takeoff) * 0.4;
            let mid = takeoff + (pregate - takeoff) * 0.75;
            vec![
                wp(start, cruise_alt, v, 15.0),
                wp(mid, (cruise_alt + app_alt) / 2.0, v * 0.8, 15.0),
                wp(
                    pregate - u * 30.0,
                    app_alt,
                    ap.approach.speed_m_s.max(v * 0.7),
                    15.0,
                ),
            ]
        }
        PathTemplate::GoAroundClimbOut => {
            let l = geometry.landing;
            vec![
                wp(pregate - u * 40.0, app_alt, v, 15.0),
                wp(
                    l - u * 30.0,
                    app_alt.max(ap.safety.min_enroute_altitude_m + 5.0),
                    v * 0.8,
                    15.0,
                ),
                wp(l + u * 150.0, cruise_alt, v, 15.0),
                wp(l + u * 150.0 + left * 150.0, cruise_alt, v, 15.0),
                wp(pregate + left * 150.0, cruise_alt, v, 15.0),
            ]
        }
    };
    FlightPath {
        name: format!("{t:?}"),
        waypoints,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use airship_model::math::heading_deg_to_yaw;

    fn geometry() -> ApproachGeometry {
        let ap = AutopilotConfig::default();
        ApproachGeometry::new(Vec2::new(400.0, -100.0), heading_deg_to_yaw(270.0), &ap)
    }

    #[test]
    fn templates_are_valid() {
        let ap = AutopilotConfig::default();
        let v = AirshipParams::default();
        for t in PathTemplate::ALL {
            let p = path_template(t, Vec2::ZERO, &geometry(), &ap);
            assert!(!p.waypoints.is_empty());
            let r = validate_flight_path(&p, Vec2::ZERO, &v, &ap);
            assert!(!r.has_errors(), "{t:?}: {:?}", r.issues);
        }
    }

    #[test]
    fn rejects_bad_waypoints() {
        let ap = AutopilotConfig::default();
        let v = AirshipParams::default();
        let path = FlightPath {
            name: "bad".into(),
            waypoints: vec![
                Waypoint {
                    x_m: 100.0,
                    y_m: 0.0,
                    altitude_m: 3.0,
                    heading_deg: None,
                    speed_m_s: 4.0,
                    tolerance_m: 10.0,
                },
                Waypoint {
                    x_m: 105.0,
                    y_m: 0.0,
                    altitude_m: 40.0,
                    heading_deg: None,
                    speed_m_s: 40.0,
                    tolerance_m: 10.0,
                },
            ],
        };
        let r = validate_flight_path(&path, Vec2::ZERO, &v, &ap);
        let fields: Vec<_> = r.errors().map(|i| i.field.clone()).collect();
        assert!(
            fields.iter().any(|f| f == "waypoints[0].altitude_m"),
            "{fields:?}"
        );
        assert!(fields.iter().any(|f| f == "waypoints[1].speed_m_s"));
        assert!(fields.iter().any(|f| f == "waypoints[1]"), "too close");
    }

    #[test]
    fn warns_on_infeasible_climb_gradient() {
        let ap = AutopilotConfig::default();
        let v = AirshipParams::default();
        let path = FlightPath {
            name: "steep".into(),
            waypoints: vec![Waypoint {
                x_m: 50.0,
                y_m: 0.0,
                altitude_m: 140.0,
                heading_deg: None,
                speed_m_s: 6.0,
                tolerance_m: 10.0,
            }],
        };
        let r = validate_flight_path(&path, Vec2::ZERO, &v, &ap);
        assert!(!r.has_errors());
        assert!(r.warnings().any(|i| i.message.contains("climb rate")));
    }
}
